import{_ as a,o as n,c as e,ag as i}from"./chunks/framework.gmyryY1Z.js";const u=JSON.parse('{"title":"Architecture Overview","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/architecture.md","filePath":"en/guide/architecture.md","lastUpdated":null}'),t={name:"en/guide/architecture.md"};function p(l,s,r,o,c,d){return n(),e("div",null,[...s[0]||(s[0]=[i(`<h1 id="architecture-overview" tabindex="-1">Architecture Overview <a class="header-anchor" href="#architecture-overview" aria-label="Permalink to &quot;Architecture Overview&quot;">​</a></h1><p>Fast Vue3 is a <strong>Vue3 Monorepo Engineering Platform</strong>, not just another admin template. Its core positioning:</p><blockquote><p>A reusable Vue3 PC-side engineering foundation that integrates multiple mainstream admin UI ecosystems, serving as a long-term evolving frontend infrastructure platform.</p></blockquote><h2 id="engineering-layers" tabindex="-1">Engineering Layers <a class="header-anchor" href="#engineering-layers" aria-label="Permalink to &quot;Engineering Layers&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│                     apps/                           │</span></span>
<span class="line"><span>│  web-antd  web-ele  web-naive  web-arco  web-tdesign│</span></span>
<span class="line"><span>│  (Independent apps — own routing, layout, theme)    │</span></span>
<span class="line"><span>└─────────────────┬───────────────────────────────────┘</span></span>
<span class="line"><span>                  │ depends on</span></span>
<span class="line"><span>┌─────────────────▼───────────────────────────────────┐</span></span>
<span class="line"><span>│                   packages/                         │</span></span>
<span class="line"><span>│  @core/shared  utils  stores  locales               │</span></span>
<span class="line"><span>│  effects/request  effects/access                    │</span></span>
<span class="line"><span>│  (Business foundation — shared by all apps)         │</span></span>
<span class="line"><span>└─────────────────┬───────────────────────────────────┘</span></span>
<span class="line"><span>                  │ tooling</span></span>
<span class="line"><span>┌─────────────────▼───────────────────────────────────┐</span></span>
<span class="line"><span>│                  internal/                          │</span></span>
<span class="line"><span>│  vite-config  tsconfig  lint-configs                │</span></span>
<span class="line"><span>│  (Engineering infrastructure — no business logic)   │</span></span>
<span class="line"><span>└─────────────────────────────────────────────────────┘</span></span></code></pre></div><h2 id="core-technical-decisions" tabindex="-1">Core Technical Decisions <a class="header-anchor" href="#core-technical-decisions" aria-label="Permalink to &quot;Core Technical Decisions&quot;">​</a></h2><h3 id="pnpm-workspace-catalog" tabindex="-1">pnpm Workspace + Catalog <a class="header-anchor" href="#pnpm-workspace-catalog" aria-label="Permalink to &quot;pnpm Workspace + Catalog&quot;">​</a></h3><p><code>pnpm-workspace.yaml</code> manages all dependency versions through the <code>catalog:</code> field:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">catalog</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  vue</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">^3.5.17</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  vite</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">^7.3.3</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  typescript</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">^5.9.3</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # ... all UI library versions</span></span></code></pre></div><p>All workspace packages reference <code>catalog:</code> in <code>package.json</code>, ensuring version consistency.</p><h3 id="turbo-task-orchestration" tabindex="-1">Turbo Task Orchestration <a class="header-anchor" href="#turbo-task-orchestration" aria-label="Permalink to &quot;Turbo Task Orchestration&quot;">​</a></h3><p><code>turbo.json</code> defines task dependencies:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;tasks&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;build&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;dependsOn&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;^build&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">] },</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;dev&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;dependsOn&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;^build&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">], </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;persistent&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;cache&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>The <code>dependsOn: [&quot;^build&quot;]</code> in the <code>dev</code> task ensures that all dependency packages (especially <code>@fast-vue3/vite-config</code>) are pre-built before any app starts.</p><h3 id="vite-config-pre-compilation-strategy" tabindex="-1">vite-config Pre-compilation Strategy <a class="header-anchor" href="#vite-config-pre-compilation-strategy" aria-label="Permalink to &quot;vite-config Pre-compilation Strategy&quot;">​</a></h3><p><code>@fast-vue3/vite-config</code> is a special engineering package:</p><ul><li>Referenced in <code>apps/</code>&#39; <code>vite.config.ts</code> files</li><li>When Node.js executes <code>vite.config.ts</code>, it needs to load this package</li><li>Therefore it <strong>must be compiled to JS</strong> — cannot export TypeScript source directly</li></ul><p>Solution: Use <code>tsdown</code> (powered by Rolldown) to compile it to <code>dist/index.js</code>.</p><p>Other <code>packages/*</code> directly export TypeScript source (<code>&quot;default&quot;: &quot;./src/index.ts&quot;</code>), processed by Vite during app builds.</p><h3 id="port-allocation" tabindex="-1">Port Allocation <a class="header-anchor" href="#port-allocation" aria-label="Permalink to &quot;Port Allocation&quot;">​</a></h3><table tabindex="0"><thead><tr><th>App</th><th>UI Framework</th><th>Port</th></tr></thead><tbody><tr><td>web-antd</td><td>Ant Design Vue</td><td>3001</td></tr><tr><td>web-ele</td><td>Element Plus</td><td>3002</td></tr><tr><td>web-naive</td><td>Naive UI</td><td>3003</td></tr><tr><td>web-arco</td><td>Arco Design</td><td>3004</td></tr><tr><td>web-tdesign</td><td>TDesign Vue Next</td><td>3005</td></tr></tbody></table><h2 id="app-internal-structure" tabindex="-1">App Internal Structure <a class="header-anchor" href="#app-internal-structure" aria-label="Permalink to &quot;App Internal Structure&quot;">​</a></h2><p>Each <code>apps/*</code> app follows a consistent structure:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>apps/web-{name}/</span></span>
<span class="line"><span>├── src/</span></span>
<span class="line"><span>│   ├── api/</span></span>
<span class="line"><span>│   │   ├── http.ts          # createHttpClient + createRequest instance</span></span>
<span class="line"><span>│   │   └── user/</span></span>
<span class="line"><span>│   │       └── index.ts     # User-related API</span></span>
<span class="line"><span>│   ├── plugins/</span></span>
<span class="line"><span>│   │   └── {name}.ts        # UI framework setup function</span></span>
<span class="line"><span>│   ├── router/</span></span>
<span class="line"><span>│   │   └── index.ts         # Router config + setupAccessGuard</span></span>
<span class="line"><span>│   ├── views/</span></span>
<span class="line"><span>│   │   ├── index.vue         # Main layout (sidebar + header)</span></span>
<span class="line"><span>│   │   ├── login/</span></span>
<span class="line"><span>│   │   │   └── index.vue    # Login page</span></span>
<span class="line"><span>│   │   └── dashboard/</span></span>
<span class="line"><span>│   │       └── index.vue    # Dashboard page</span></span>
<span class="line"><span>│   ├── App.vue</span></span>
<span class="line"><span>│   └── main.ts</span></span>
<span class="line"><span>├── mock/                     # Mock API data</span></span>
<span class="line"><span>├── types/</span></span>
<span class="line"><span>│   └── env.d.ts             # Environment variable type declarations</span></span>
<span class="line"><span>├── .env                     # Base env vars</span></span>
<span class="line"><span>├── .env.development         # Dev env vars</span></span>
<span class="line"><span>├── .env.production          # Prod env vars</span></span>
<span class="line"><span>├── tsconfig.json            # Extends @fast-vue3/tsconfig/web-app</span></span>
<span class="line"><span>└── vite.config.ts           # Uses @fast-vue3/vite-config defineConfig</span></span></code></pre></div><h2 id="shared-infrastructure" tabindex="-1">Shared Infrastructure <a class="header-anchor" href="#shared-infrastructure" aria-label="Permalink to &quot;Shared Infrastructure&quot;">​</a></h2><p>All apps share via <code>packages/*</code>:</p><ul><li><strong>@fast-vue3/shared</strong> — Core types &amp; constants</li><li><strong>@fast-vue3/utils</strong> — Auth utils, date formatting, helpers</li><li><strong>@fast-vue3/stores</strong> — Pinia stores (useUserStore/useAppStore) + persistedstate</li><li><strong>@fast-vue3/locales</strong> — zh-CN / en-US i18n resources</li><li><strong>@fast-vue3/request</strong> — Axios wrapper (createHttpClient/createRequest)</li><li><strong>@fast-vue3/access</strong> — Route access guard (setupAccessGuard) + v-access directive</li></ul>`,27)])])}const k=a(t,[["render",p]]);export{u as __pageData,k as default};
